/* js/app.js - TodoMVC vanilla JS implementation */
(function () {
  'use strict';

  var ENTER_KEY = 13;
  var ESCAPE_KEY = 27;
  var STORAGE_KEY = 'todos-vanillajs';

  // ---- Model ----
  var todoData = loadTodos();

  function saveTodos() {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(todoData));
  }

  function loadTodos() {
    try {
      return JSON.parse(localStorage.getItem(STORAGE_KEY)) || [];
    } catch (_) {
      return [];
    }
  }

  function nextId() {
    var max = 0;
    todoData.forEach(function (t) { if (t.id > max) max = t.id; });
    return max + 1;
  }

  // ---- View helpers ----
  var todoList = document.querySelector('.todo-list');
  var mainEl = document.querySelector('.main');
  var footerEl = document.querySelector('.footer');
  var newTodoInput = document.querySelector('.new-todo');
  var todoCountEl = document.querySelector('.todo-count');
  var clearCompletedBtn = document.querySelector('.clear-completed');
  var toggleAllCheckbox = document.querySelector('#toggle-all');
  var filterLinks = document.querySelectorAll('.filters a');

  var filter = 'all';

  // ---- Router ----
  function router() {
    var hash = window.location.hash || '#/';
    if (hash === '#/' || hash === '' || hash === '#') {
      filter = 'all';
    } else if (hash === '#/active') {
      filter = 'active';
    } else if (hash === '#/completed') {
      filter = 'completed';
    }
    render();
  }

  window.addEventListener('hashchange', router);
  window.addEventListener('load', router);

  // ---- Render ----
  function render() {
    var filtered = getFilteredTodos();
    var allCompleted = todoData.length > 0 && todoData.every(function (t) { return t.completed; });

    // Build list
    var html = '';
    filtered.forEach(function (todo) {
      var liClass = '';
      if (todo.completed) liClass += 'completed';
      html += '<li data-id="' + todo.id + '" class="' + liClass + '">';
      html += '  <div class="view">';
      html += '    <input class="toggle" type="checkbox"' + (todo.completed ? ' checked' : '') + '>';
      html += '    <label>' + escapeHtml(todo.title) + '</label>';
      html += '    <button class="destroy"></button>';
      html += '  </div>';
      html += '  <input class="edit" value="' + escapeHtml(todo.title) + '">';
      html += '</li>';
    });
    todoList.innerHTML = html;

    // Toggle all
    toggleAllCheckbox.checked = allCompleted;

    // Main & footer visibility
    var hasTodos = todoData.length > 0;
    mainEl.style.display = hasTodos ? 'block' : 'none';
    footerEl.style.display = hasTodos ? 'block' : 'none';

    // Count
    var activeCount = todoData.filter(function (t) { return !t.completed; }).length;
    var word = activeCount === 1 ? 'item' : 'items';
    todoCountEl.innerHTML = '<strong>' + activeCount + '</strong> ' + word + ' left';

    // Clear completed
    var hasCompleted = todoData.some(function (t) { return t.completed; });
    clearCompletedBtn.style.display = hasCompleted ? 'block' : 'none';

    // Filter selected
    filterLinks.forEach(function (link) {
      var href = link.getAttribute('href');
      if ((filter === 'all' && (href === '#/' || href === '#')) ||
          (filter === 'active' && href === '#/active') ||
          (filter === 'completed' && href === '#/completed')) {
        link.classList.add('selected');
      } else {
        link.classList.remove('selected');
      }
    });
  }

  function getFilteredTodos() {
    if (filter === 'active') return todoData.filter(function (t) { return !t.completed; });
    if (filter === 'completed') return todoData.filter(function (t) { return t.completed; });
    return todoData;
  }

  function escapeHtml(str) {
    var div = document.createElement('div');
    div.appendChild(document.createTextNode(str));
    return div.innerHTML;
  }

  // ---- New todo ----
  newTodoInput.addEventListener('keypress', function (e) {
    if (e.keyCode !== ENTER_KEY) return;
    var val = newTodoInput.value.trim();
    if (val === '') return;
    todoData.push({ id: nextId(), title: val, completed: false });
    newTodoInput.value = '';
    saveTodos();
    render();
  });

  // ---- Event delegation for todo list ----
  todoList.addEventListener('click', function (e) {
    var li = e.target.closest('li');
    if (!li) return;
    var id = Number(li.dataset.id);

    // Toggle checkbox
    if (e.target.classList.contains('toggle')) {
      toggleTodo(id);
    }

    // Destroy button
    if (e.target.classList.contains('destroy')) {
      destroyTodo(id);
    }
  });

  // Double-click to edit
  todoList.addEventListener('dblclick', function (e) {
    var label = e.target.closest('label');
    if (!label) return;
    var li = label.closest('li');
    if (!li) return;
    enterEditMode(li);
  });

  // Edit input events (delegated)
  todoList.addEventListener('focusout', function (e) {
    if (!e.target.classList.contains('edit')) return;
    var li = e.target.closest('li');
    if (!li) return;
    if (!li.classList.contains('editing')) return;
    submitEdit(li);
  });

  todoList.addEventListener('keypress', function (e) {
    if (e.keyCode !== ENTER_KEY) return;
    var editInput = e.target.closest('.edit');
    if (!editInput) return;
    var li = editInput.closest('li');
    if (!li) return;
    if (!li.classList.contains('editing')) return;
    submitEdit(li);
  });

  todoList.addEventListener('keydown', function (e) {
    if (e.keyCode !== ESCAPE_KEY) return;
    var editInput = e.target.closest('.edit');
    if (!editInput) return;
    var li = editInput.closest('li');
    if (!li) return;
    if (!li.classList.contains('editing')) return;
    cancelEdit(li);
  });

  // ---- Todo operations ----
  function toggleTodo(id) {
    todoData.forEach(function (t) {
      if (t.id === id) t.completed = !t.completed;
    });
    saveTodos();
    render();
  }

  function destroyTodo(id) {
    todoData = todoData.filter(function (t) { return t.id !== id; });
    saveTodos();
    render();
  }

  function enterEditMode(li) {
    li.classList.add('editing');
    var editInput = li.querySelector('.edit');
    editInput.focus();
    editInput.selectionStart = editInput.selectionEnd = editInput.value.length;
  }

  function submitEdit(li) {
    var editInput = li.querySelector('.edit');
    var val = editInput.value.trim();
    var id = Number(li.dataset.id);

    li.classList.remove('editing');

    if (val === '') {
      destroyTodo(id);
      return;
    }

    todoData.forEach(function (t) {
      if (t.id === id) t.title = val;
    });
    saveTodos();
    render();
  }

  function cancelEdit(li) {
    li.classList.remove('editing');
    var editInput = li.querySelector('.edit');
    var id = Number(li.dataset.id);
    todoData.forEach(function (t) {
      if (t.id === id) editInput.value = t.title;
    });
    render();
  }

  // ---- Mark all as complete ----
  toggleAllCheckbox.addEventListener('change', function () {
    var completed = toggleAllCheckbox.checked;
    todoData.forEach(function (t) { t.completed = completed; });
    saveTodos();
    render();
  });

  // ---- Clear completed ----
  clearCompletedBtn.addEventListener('click', function () {
    todoData = todoData.filter(function (t) { return !t.completed; });
    saveTodos();
    render();
  });
})();

const { Then, When, Given } = require('@cucumber/cucumber');
const { expect } = require('expect');

// ---- Helpers ----

function getTodoList(world) {
  return world.document.querySelector('.todo-list');
}

function getTodoItems(world) {
  return getTodoList(world).querySelectorAll('li');
}

function findTodoItem(world, title) {
  var items = getTodoItems(world);
  for (var i = 0; i < items.length; i++) {
    var label = items[i].querySelector('.view label');
    if (label && label.textContent.trim() === title) return items[i];
  }
  return null;
}

function getNewTodoInput(world) {
  return world.document.querySelector('.new-todo');
}

function getMain(world) {
  return world.document.querySelector('.main');
}

function getFooter(world) {
  return world.document.querySelector('.footer');
}

function getToggleAll(world) {
  return world.document.querySelector('#toggle-all');
}

function getClearCompleted(world) {
  return world.document.querySelector('.clear-completed');
}

function getTodoCount(world) {
  return world.document.querySelector('.todo-count');
}

// ---- Given ----

Given('the app is loaded fresh', function () {
  // The world.js Before hook already loads the app fresh per scenario.
  // Clear localStorage so no stale data survives.
  this.localStorage.clear();
  this.loadApp();
});

Given('there are no todos', function () {
  this.localStorage.clear();
  this.loadApp();
});

Given('I have a todo {string}', function (title) {
  addTodo(this, title);
});

Given('I have todos {string} and {string}', function (title1, title2) {
  addTodo(this, title1);
  addTodo(this, title2);
});

Given('I have completed todos {string} and {string}', function (title1, title2) {
  addTodo(this, title1);
  addTodo(this, title2);
  var items = getTodoItems(this);
  for (var i = 0; i < items.length; i++) {
    var cb = items[i].querySelector('.toggle');
    if (cb) { cb.checked = true; cb.dispatchEvent(new this.window.Event('click', { bubbles: true })); }
  }
});

Given('the input field is focused', function () {
  // The input has autofocus; ensure it's focused
  getNewTodoInput(this).focus();
});

Given('the todo {string} is in editing mode', function (title) {
  var li = findTodoItem(this, title);
  if (!li) throw new Error('Todo "' + title + '" not found');
  var label = li.querySelector('.view label');
  label.dispatchEvent(new this.window.Event('dblclick', { bubbles: true }));
});

Given('the todo {string} is in editing mode with value {string}', function (title, value) {
  var li = findTodoItem(this, title);
  if (!li) throw new Error('Todo "' + title + '" not found');
  var label = li.querySelector('.view label');
  label.dispatchEvent(new this.window.Event('dblclick', { bubbles: true }));
  var editInput = li.querySelector('.edit');
  editInput.value = value;
});

// ---- When ----

When('I type {string} in the new-todo input and press Enter', function (value) {
  var input = getNewTodoInput(this);
  input.value = value;
  var event = new this.window.KeyboardEvent('keypress', { keyCode: 13, bubbles: true });
  input.dispatchEvent(event);
});

When('I click the {string} toggle', function (label) {
  if (label === 'Mark all as complete') {
    getToggleAll(this).click();
  } else {
    throw new Error('Unknown toggle: ' + label);
  }
});

When('I toggle the first todo as completed', function () {
  var items = getTodoItems(this);
  if (items.length === 0) throw new Error('No todos to toggle');
  var cb = items[0].querySelector('.toggle');
  cb.click();
});

When('I toggle all todos as completed', function () {
  var items = getTodoItems(this);
  for (var i = 0; i < items.length; i++) {
    var cb = items[i].querySelector('.toggle');
    if (!cb.checked) cb.click();
  }
});

When('I click the checkbox for {string}', function (title) {
  var li = findTodoItem(this, title);
  if (!li) throw new Error('Todo "' + title + '" not found');
  li.querySelector('.toggle').click();
});

When('I double-click the label for {string}', function (title) {
  var li = findTodoItem(this, title);
  if (!li) throw new Error('Todo "' + title + '" not found');
  var label = li.querySelector('.view label');
  label.dispatchEvent(new this.window.Event('dblclick', { bubbles: true }));
});

When('I hover over the todo {string}', function (title) {
  var li = findTodoItem(this, title);
  if (!li) throw new Error('Todo "' + title + '" not found');
  li.dispatchEvent(new this.window.Event('mouseenter', { bubbles: true }));
});

When('I click the destroy button for {string}', function (title) {
  var li = findTodoItem(this, title);
  if (!li) throw new Error('Todo "' + title + '" not found');
  li.querySelector('.destroy').click();
});

When('I change the value to {string} and press Enter', function (value) {
  var editInput = this.document.querySelector('.editing .edit');
  if (!editInput) throw new Error('No todo is in editing mode');
  editInput.value = value;
  var event = new this.window.KeyboardEvent('keypress', { keyCode: 13, bubbles: true });
  editInput.dispatchEvent(event);
});

When('I change the value to {string} and blur the input', function (value) {
  var editInput = this.document.querySelector('.editing .edit');
  if (!editInput) throw new Error('No todo is in editing mode');
  editInput.value = value;
  editInput.dispatchEvent(new this.window.Event('focusout', { bubbles: true }));
});

When('I press Escape', function () {
  var editInput = this.document.querySelector('.editing .edit');
  if (!editInput) throw new Error('No todo is in editing mode');
  var event = new this.window.KeyboardEvent('keydown', { keyCode: 27, bubbles: true });
  editInput.dispatchEvent(event);
});

When('I edit {string} to an empty value', function (title) {
  var li = findTodoItem(this, title);
  if (!li) throw new Error('Todo "' + title + '" not found');
  var label = li.querySelector('.view label');
  label.dispatchEvent(new this.window.Event('dblclick', { bubbles: true }));
  var editInput = li.querySelector('.edit');
  editInput.value = '';
  var event = new this.window.KeyboardEvent('keypress', { keyCode: 13, bubbles: true });
  editInput.dispatchEvent(event);
});

When('I mark {string} as completed', function (title) {
  var li = findTodoItem(this, title);
  if (!li) throw new Error('Todo "' + title + '" not found');
  var cb = li.querySelector('.toggle');
  if (!cb.checked) cb.click();
});

When('I add a todo {string}', function (title) {
  addTodo(this, title);
});

When('I click {string}', function (label) {
  if (label === 'Clear completed') {
    getClearCompleted(this).click();
  } else {
    throw new Error('Unknown button: ' + label);
  }
});

When('I reload the app', function () {
  // Simulate reload: clear window, reload from localStorage
  this.disposeApp();
  this.loadApp();
});

When('{string} is completed', function (title) {
  var li = findTodoItem(this, title);
  if (!li) throw new Error('Todo "' + title + '" not found');
  var cb = li.querySelector('.toggle');
  if (!cb.checked) cb.click();
});

When('I visit the {string} route', function (route) {
  this.navigate(route);
});

When('I toggle {string} as completed', function (title) {
  var li = findTodoItem(this, title);
  if (!li) throw new Error('Todo "' + title + '" not found');
  var cb = li.querySelector('.toggle');
  if (!cb.checked) cb.click();
});

// ---- Then ----

Then('{string} is hidden', function (selector) {
  var el;
  if (selector === '#main') el = getMain(this);
  else if (selector === '#footer') el = getFooter(this);
  else if (selector === 'the {string} button') {
    // Pattern match
  } else {
    el = this.document.querySelector(selector);
  }
  if (!el) throw new Error('Element "' + selector + '" not found');
  var display = this.window.getComputedStyle(el).display;
  if (display !== 'none') throw new Error('Expected "' + selector + '" to be hidden but display is "' + display + '"');
});

Then('a new todo {string} appears in the list', function (title) {
  var li = findTodoItem(this, title);
  if (!li) throw new Error('Expected todo "' + title + '" to appear in the list');
});

Then('the new-todo input is cleared', function () {
  var input = getNewTodoInput(this);
  if (input.value !== '') throw new Error('Expected input to be cleared, got "' + input.value + '"');
});

Then('the todo list is empty', function () {
  var items = getTodoItems(this);
  if (items.length !== 0) throw new Error('Expected empty list, got ' + items.length + ' items');
});

Then('all todos are marked completed', function () {
  var items = getTodoItems(this);
  for (var i = 0; i < items.length; i++) {
    if (!items[i].classList.contains('completed')) {
      var label = items[i].querySelector('.view label');
      throw new Error('Expected todo "' + (label ? label.textContent : '?') + '" to be completed');
    }
  }
});

Then('all todos are marked active', function () {
  var items = getTodoItems(this);
  for (var i = 0; i < items.length; i++) {
    if (items[i].classList.contains('completed')) {
      var label = items[i].querySelector('.view label');
      throw new Error('Expected todo "' + (label ? label.textContent : '?') + '" to be active');
    }
  }
});

Then('the {string} toggle is unchecked', function (label) {
  if (label === 'Mark all as complete') {
    if (getToggleAll(this).checked) throw new Error('Expected toggle-all to be unchecked');
  }
});

Then('the {string} toggle is checked', function (label) {
  if (label === 'Mark all as complete') {
    if (!getToggleAll(this).checked) throw new Error('Expected toggle-all to be checked');
  }
});

Then('{string} is marked completed', function (title) {
  var li = findTodoItem(this, title);
  if (!li) throw new Error('Todo "' + title + '" not found');
  if (!li.classList.contains('completed')) throw new Error('Expected todo "' + title + '" to be completed');
});

Then('the todo {string} is in editing mode', function (title) {
  var li = findTodoItem(this, title);
  if (!li) throw new Error('Todo "' + title + '" not found');
  if (!li.classList.contains('editing')) throw new Error('Expected todo "' + title + '" to be in editing mode');
});

Then('the destroy button for {string} is visible', function (title) {
  var li = findTodoItem(this, title);
  if (!li) throw new Error('Todo "' + title + '" not found');
  var destroy = li.querySelector('.destroy');
  if (!destroy) throw new Error('Destroy button not found for "' + title + '"');
  // destroy is visible by default in the base CSS; just check it exists
});

Then('the todo {string} is removed', function (title) {
  var li = findTodoItem(this, title);
  if (li) throw new Error('Expected todo "' + title + '" to be removed');
});

Then('the todo {string} is renamed to {string}', function (oldTitle, newTitle) {
  var li = findTodoItem(this, newTitle);
  if (!li) throw new Error('Expected todo "' + newTitle + '" to exist');
  var oldLi = findTodoItem(this, oldTitle);
  if (oldLi) throw new Error('Expected todo "' + oldTitle + '" to no longer exist');
});

Then('the todo {string} is not in editing mode', function (title) {
  var li = findTodoItem(this, title);
  if (!li) throw new Error('Todo "' + title + '" not found');
  if (li.classList.contains('editing')) throw new Error('Expected todo "' + title + '" to not be in editing mode');
});

Then('the todo value remains {string}', function (title) {
  var li = findTodoItem(this, title);
  if (!li) throw new Error('Todo "' + title + '" not found');
  var label = li.querySelector('.view label');
  if (label.textContent.trim() !== title) throw new Error('Expected label to be "' + title + '", got "' + label.textContent.trim() + '"');
});

Then('the todo count shows {string}', function (expected) {
  var countEl = getTodoCount(this);
  var text = countEl.textContent.trim();
  if (text !== expected) throw new Error('Expected count "' + expected + '", got "' + text + '"');
});

Then('there are no completed todos', function () {
  var items = getTodoItems(this);
  for (var i = 0; i < items.length; i++) {
    if (items[i].classList.contains('completed')) {
      var label = items[i].querySelector('.view label');
      throw new Error('Expected no completed todos, but "' + (label ? label.textContent : '?') + '" is completed');
    }
  }
});

